import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { supabase } from '../supabaseClient';

function Chat() {
  const navigate = useNavigate();
  const [mensagens, setMensagens] = useState([
    { role: 'assistant', content: 'Olá. Sou o seu eu digital. Pode me perguntar qualquer coisa sobre a sua história.' }
  ]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [memorias, setMemorias] = useState('');
  const fimRef = useRef(null);

  useEffect(() => {
    const carregar = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      const { data } = await supabase
        .from('memorias')
        .select('*')
        .eq('user_id', user.id);

      if (data) {
        const texto = data.map(m => `Pergunta: ${m.pergunta}\nResposta: ${m.resposta}`).join('\n\n');
        setMemorias(texto);
      }
    };
    carregar();
  }, []);

  useEffect(() => {
    fimRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [mensagens]);

  const enviar = async () => {
    if (!input.trim() || loading) return;

    const novaMensagem = { role: 'user', content: input };
    const novaLista = [...mensagens, novaMensagem];
    setMensagens(novaLista);
    setInput('');
    setLoading(true);

    try {
      const response = await fetch('http://localhost:3001/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          system: `Você é o eu digital de uma pessoa. Responda sempre em primeira pessoa, como se fosse ela mesma falando. Use apenas as memórias abaixo para responder. Se não souber algo, diga que não se lembra.\n\nMemórias:\n${memorias}`,
          messages: novaLista.map(m => ({ role: m.role, content: m.content }))
        })
      });

      const data = await response.json();
      const resposta = data.content[0].text;
      setMensagens([...novaLista, { role: 'assistant', content: resposta }]);
    } catch (err) {
      setMensagens([...novaLista, { role: 'assistant', content: 'Erro ao conectar. Tente novamente.' }]);
    }

    setLoading(false);
  };

  return (
    <div style={{
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%)',
      color: 'white',
      fontFamily: 'Georgia, serif',
      display: 'flex',
      flexDirection: 'column'
    }}>
      <div style={{ padding: '20px 30px', borderBottom: '1px solid rgba(255,255,255,0.1)', display: 'flex', alignItems: 'center', gap: '15px' }}>
        <button onClick={() => navigate('/dashboard')} style={{ background: 'transparent', border: 'none', color: 'white', fontSize: '1.2rem', cursor: 'pointer' }}>←</button>
        <h2 style={{ fontSize: '1.3rem', letterSpacing: '2px' }}>Conversa com seu eu</h2>
      </div>

      <div style={{ flex: 1, overflowY: 'auto', padding: '30px', display: 'flex', flexDirection: 'column', gap: '20px' }}>
        {mensagens.map((m, i) => (
          <div key={i} style={{
            display: 'flex',
            justifyContent: m.role === 'user' ? 'flex-end' : 'flex-start'
          }}>
            <div style={{
              maxWidth: '70%',
              padding: '15px 20px',
              borderRadius: m.role === 'user' ? '20px 20px 5px 20px' : '20px 20px 20px 5px',
              background: m.role === 'user' ? 'rgba(255,255,255,0.15)' : 'rgba(255,255,255,0.05)',
              lineHeight: 1.6
            }}>
              {m.content}
            </div>
          </div>
        ))}
        {loading && (
          <div style={{ opacity: 0.5, fontStyle: 'italic' }}>digitando...</div>
        )}
        <div ref={fimRef} />
      </div>

      <div style={{ padding: '20px 30px', borderTop: '1px solid rgba(255,255,255,0.1)', display: 'flex', gap: '10px' }}>
        <input
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyPress={e => e.key === 'Enter' && enviar()}
          placeholder="Faça uma pergunta..."
          style={{
            flex: 1,
            padding: '12px 20px',
            borderRadius: '25px',
            border: 'none',
            fontSize: '1rem',
            fontFamily: 'Georgia, serif',
            background: 'rgba(255,255,255,0.1)',
            color: 'white'
          }}
        />
        <button
          onClick={enviar}
          disabled={loading}
          style={{
            background: 'white',
            color: '#1a1a2e',
            border: 'none',
            padding: '12px 25px',
            borderRadius: '25px',
            cursor: 'pointer',
            fontWeight: 'bold'
          }}
        >
          →
        </button>
      </div>
    </div>
  );
}

export default Chat;
